import raw from './generated/philosophers.json';
import { PHIL_ID_ALIAS, type PhilosopherCard, type PhilosopherTheme } from '../types/schema';

/**
 * 27 fully bilingual philosopher records.
 * Generated by scripts/parse-patch.mjs from PATCH_DATA_AND_I18N.md Part 2.
 * Order follows the patch: theme groups A/B/C, ascending yearSort within each.
 */
export const philosophers: PhilosopherCard[] = raw as unknown as PhilosopherCard[];

/** Strict chronological order (used by the "按年代" view and the timeline rail). */
export const sortedByYear: PhilosopherCard[] = [...philosophers].sort((a, b) => a.yearSort - b.yearSort);

export const philosopherById = new Map(philosophers.map((p) => [p.id, p]));

/** Canonical anchor for a legacy short id used inside cognitiveEngine mappings. */
export function canonicalPhilId(shortId: string): string {
  if (shortId.startsWith('phil-')) return shortId;
  return PHIL_ID_ALIAS[shortId] ?? `phil-${shortId}`;
}

export const philosophyHref = (shortId: string): string => `/philosophy#${canonicalPhilId(shortId)}`;

/** Legacy short-id lookup so the cross-library matrix keeps working unchanged. */
export const philosopherByShortId = new Map(
  philosophers.map((p) => [p.id.replace(/^phil-/, ''), p]),
);

export const philosopherThemes: { key: PhilosopherTheme | 'all'; zh: string; en: string }[] = [
  { key: 'all', zh: '全部源流 (27)', en: 'All Philosophers (27)' },
  { key: 'chinese', zh: '东方哲思与心性 (4)', en: 'Chinese Philosophy (4)' },
  { key: 'epistemology', zh: '西方认识论与语言科学 (11)', en: 'Epistemology & Language (11)' },
  { key: 'critique', zh: '存在、伦理与社会批判 (12)', en: 'Existence, Ethics & Critique (12)' },
];

export const themeCounts = philosophers.reduce<Record<string, number>>((acc, p) => {
  acc[p.theme] = (acc[p.theme] ?? 0) + 1;
  return acc;
}, {});
